import{a as t}from"./chunk-YAXRTJVL.js";import{Kc as e,n as a}from"./chunk-XXQ56O26.js";function l(){return`<a class="text-link" href="#/career-tree">\u2190 The complete career tree</a><div class="page-intro guide-intro"><span class="eyebrow">CATALOG REVIEW \xB7 OCTOBER16,2026</span><h1>More everyday jobs. Clearer fields.</h1><p>We reviewed all 857 previously missing directory titles. 50 now have complete guided profiles.</p></div><section class="coverage-counts"><article><strong>117</strong><span>Guided profiles</span></article><article><strong>50</strong><span>New priorities included</span></article><article><strong>807</strong><span>More titles grouped into fields</span></article></section><section class="guide-input-panel"><h2>Common work belongs here too.</h2><p>Office support, retail, kitchens, delivery, safety, and hands-on care now sit beside college professions.</p><p>Employment size helped us choose. Different training routes and gaps in the tree mattered too.</p><a class="button" href="#/career-tree">Explore the full tree \u2192</a></section><details class="more-info"><summary>The 50 additions</summary><div class="priority-profile-list">${a.map(r=>`<a href="#/career/${r.id}">${e(r.title)} \u2192</a>`).join("")}</div></details><details class="more-info"><summary>How every directory title was reviewed</summary><p>${e(t.method)}</p><p>We used all 831 line-item BLS occupation groups.856 of the857 titles have an exact or broader national employment reference; Legislators has no published count in this table. Local counts use the 2024 Capital Area workforce district, which is smaller than the Austin metro. We do not treat these as interchangeable years or places.</p><p>Narrow O*NET specialties often share one BLS employment group. That group\u2019s workers are counted once. Missing or suppressed counts never mean zero jobs.</p><p>The 50 are an editorial coverage set, not the mathematical50 largest jobs. Remaining titles include both common occupations and narrow specialties. A grouped role does not inherit another career\u2019s license or salary.</p><a href="./catalog-directory-review.json.gz" download>Download the full857-title review \u2192</a> \xB7 <a href="https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm" target="_blank" rel="noopener noreferrer">BLS employment source \u2197</a></details><details class="more-info"><summary>What \u201Ccomplete profile\u201D means</summary><p>Daily work, skills, helpful qualities, interests, preparation, Texas requirements, education costs and aid, Austin wage evidence, illustrative later-career pay, and a route to My Plan.</p><p>116 profiles match official directory titles. Tattoo is a separate editorial profile within a broader artistic occupation. The 923 directory titles are accounted for by 116 guided profiles and 807 grouped titles.</p><a href="#/source-review">Financial sources and estimates \u2192</a></details>`}export{l as catalogCoveragePage};
